INSERT INTO `mx_motor_category` VALUES (1,100,'High / Low Voltage AC & DC Motors','unnamed.jpg','<p>The complete CG Power / Crompton motor portfolio through one authorised channel partner — high voltage machines to 15 MW, low voltage industrial motors, energy-efficient IE2/IE3/IE4 ranges, hazardous-area certified motors, and DC machines. BES has supplied Indian industry from Fort, Mumbai since 1957, with application engineering support on every inquiry.</p>',NULL,0,'motor/high-low-voltage-ac-dc-motors','en',NULL,0,1),(5,102,'Safe Area Single Phase AC Motor','unnamed.jpg',NULL,NULL,0,'motor/single-phase-ac-motor/safe-area-single-phase-ac-motor','en',NULL,0,0),(6,102,'Hazardous Area Single Phase AC Motor','unnamed.jpg',NULL,NULL,0,'motor/single-phase-ac-motor/hazardous-area-single-phase-ac-motor','en',NULL,0,0),(7,24,'Laminated Yoke DC Motor','unnamed.jpg',NULL,NULL,0,'motor/dc-motors/laminated-yoke-dc-motor','en',NULL,0,0),(8,24,'Solid Yoke DC Motor','unnamed.jpg',NULL,NULL,0,'motor/dc-motor/solid-yoke-dc-motor','en',NULL,0,0),(9,3,'DC Motor 3',NULL,NULL,NULL,0,'motor/dc-motor/dc-motor-3','en',NULL,0,0),(11,22,'Squirrel Cage Motor IE2 Efficiency','unnamed.jpg',NULL,NULL,0,'motor/low-voltage-ac-motor/squirrel-cage-motor-ie2-efficiency','en',NULL,0,0),(12,22,'Squirrel Cage Motor IE3 Efficiency','unnamed.jpg',NULL,NULL,0,'motor/low-voltage-ac-motor/squirrel-cage-motor-ie3-efficiency','en',NULL,0,0),(13,22,'Squirrel Cage Motor IE4 Efficiency','unnamed.jpg',NULL,NULL,0,'motor/low-voltage-ac-motor/squirrel-cage-motor-ie4-efficiency','en',NULL,0,0),(14,22,'Slip Ring Induction Motors','unnamed.jpg',NULL,NULL,0,'motor/low-voltage-ac-motor/slip-ring-induction-motors','en',NULL,0,0),(15,25,'Safe Area High Voltage AC Motor','unnamed.jpg',NULL,NULL,0,'motor/high-voltage-ac-motors/safe-area-high-voltage-ac-motor','en',NULL,0,0),(16,25,'Hazardous Area High Voltage AC Motor','unnamed.jpg',NULL,NULL,0,'motor/high-voltage-ac-motors/hazardous-area-high-voltage-ac-motor','en',NULL,0,0),(17,11,'Safe Area Squirrel Cage IE2 Motors','unnamed.jpg',NULL,NULL,0,'motor/low-voltage-ac-motor/squirrel-cage-motor-ie2-efficiency/safe-area-squirrel-cage-ie2-motors','en',NULL,0,0),(18,1,'AC Motor1 third leve','unnamed.jpg','Testing',NULL,0,'motor/dc-motor/solid-yoke-dc-motor/ac-motor1-third-leve','en',NULL,0,0),(19,100,'Electric','unnamed.jpg',NULL,NULL,0,'electric','en',NULL,0,0),(20,1,'High Voltage Motors','unnamed.jpg','<p>High voltage motors from 3.3 kV to 11 kV for heavy industry — squirrel cage and slip-ring induction machines, synchronous motors, and cooling variants (CACA, CACW, TETV) to 15 MW. These CG machines drive fans, pumps, compressors, and mills in power plants, cement, steel, and process industries. Full project support: sizing, factory testing, commissioning coordination.</p>',NULL,1,'motor/high-low-voltage-ac-dc-motors/high-voltage-motors',NULL,NULL,0,1),(21,1,'Low Voltage Motors','unnamed.jpg','<p>Low voltage three-phase induction motors — the backbone of Indian industry. Cast iron and aluminium body ranges from 0.37 kW to 315 kW covering pumps, fans, compressors, conveyors, and machine tools. Includes premium AXELERA process-performance motors and SMARTOR smart-monitoring variants. All IE2 minimum efficiency, with IE3/IE4 options for energy-conscious plants.</p>',NULL,2,'motor/high-low-voltage-ac-dc-motors/low-voltage-motors',NULL,NULL,0,1),(22,1,'Energy Efficient Motors','unnamed.jpg','<p>Energy-efficient motors cut electricity bills at the source — IE2, IE3, and IE4 efficiency classes deliver 2-7% lower losses than older motors, often paying back the price premium within 18 months on continuous duty. The Crompton Apex series leads this range. Essential for BEE compliance and any plant serious about operating cost and carbon footprint.</p>',NULL,3,'motor/high-low-voltage-ac-dc-motors/energy-efficient-motors',NULL,NULL,0,1),(23,1,'Motors for Hazardous Area (LV)','unnamed.jpg','<p>Hazardous area motors for LV applications in Zone 1 and Zone 2 — flameproof Ex db, increased safety Ex eb, and non-sparking Ex ec constructions, all PESO approved with IECEx certification. Standard supply to refineries, chemical plants, paint shops, and pharma across India. BES manages certification documentation and zone-classification guidance.</p>',NULL,4,'motor/high-low-voltage-ac-dc-motors/motors-for-hazardous-area-lv',NULL,NULL,0,1),(24,1,'DC Motors','unnamed.jpg','<p>DC motors for applications demanding precise speed and torque control — rolling mills, cranes, extruders, and legacy drive systems. Laminated and solid yoke constructions from CG\'s large machines division, plus modern brushless DC (BLDC) motors for e-mobility and energy-efficient OEM equipment. Rewinding and spares support for installed DC machines.</p>',NULL,6,'motor/high-low-voltage-ac-dc-motors/dc-motors',NULL,NULL,0,1),(25,1,'Motors for Hazardous Areas (HV)','unnamed.jpg','<p>High voltage hazardous area motors for Zone 1 and Zone 2 gas atmospheres — flameproof Ex db, increased safety Ex eb, non-sparking Ex n, and pressurized Ex px/pz machines from 3.3 kV to 11 kV. Deployed in refineries, petrochemical complexes, and gas processing across India. Complete IECEx, ATEX, and PESO documentation with every machine.</p>',NULL,5,'motor/high-low-voltage-ac-dc-motors/motors-for-hazardous-areas-hv',NULL,NULL,0,1),(26,1,'Special Application Motors','unnamed.jpg','<p>Special application motors engineered for demanding duties standard motors cannot handle — brake motors for hoists and cranes, roller table motors for steel mills, oil well pump motors, cement mill double-cage designs, crusher duty, and smoke-extraction fire motors. Each built to survive its specific environment: heat, dust, impact, or emergency duty.</p>',NULL,7,'motor/high-low-voltage-ac-dc-motors/special-application-motors',NULL,NULL,0,1),(27,0,'Motor',NULL,NULL,NULL,0,'motor','en',NULL,0,0),(100,0,'Motor','unnamed.jpg','<p>Electric motors for every industrial and commercial application — browse by voltage class, efficiency rating, or application type. As CG Power / Crompton authorised channel partners since 1957, BES supplies genuine motors from fractional HP to 15 MW with expert selection support from our Mumbai and Ahmedabad offices.</p>',NULL,0,'motor',NULL,NULL,0,1),(101,100,'FHP / Commercial Motors','unnamed.jpg','<p>Fractional horsepower and commercial motors for OEM equipment, appliances, and light industry — single-phase motors, NEMA frame exports, cooler and fan motors, and application-specific designs. High-volume OEM supply with custom shaft, mounting, and nameplate options. The range Indian equipment manufacturers build on.</p>',NULL,1,'motor/fhp-commercial-motors','en',NULL,0,1),(102,101,'Single Phase Motors','unnamed.jpg','<p>Single-phase motors run on standard 230V domestic supply — capacitor-start for high starting torque (compressors, pumps), capacitor-run for continuous duty (fans, blowers), PSC for quiet HVAC service, and split-phase for light loads. Ratings from 0.18 kW to 2.2 kW. The practical choice where three-phase supply is unavailable.</p>',NULL,1,'motor/fhp-commercial-motors/single-phase-motors',NULL,NULL,0,1),(103,101,'3 Phase Motors - Rolled Steel Body',NULL,NULL,NULL,2,'motor/fhp-commercial-motors/3-phase-motors-rolled-steel-body',NULL,NULL,0,0),(104,101,'Application Specific Motors','unnamed.jpg','<p>Application-specific motors matched to their duty — cooler motors, flange-mounted designs, huller and pulveriser motors for food processing, textile industry motors, poultry fan motors, HVAC blowers, and transformer cooling fans. Decades of application knowledge mean each motor is specified correctly for its real working conditions, not just its power rating.</p>',NULL,3,'motor/fhp-commercial-motors/application-specific-motors',NULL,NULL,0,1),(105,100,'Drives and Automation','unnamed.jpg','<p>Drives and automation complete the motor system — Emotron variable frequency drives for speed control and energy savings, soft starters for smooth motor starting, and medium-voltage drives for large machines. VFDs typically cut energy 30-50% on variable loads like pumps and fans. BES supports drive sizing, harmonics assessment, and commissioning.</p>',NULL,2,'motor/drives-and-automation',NULL,NULL,0,1),(106,105,'Industrial Drives','unnamed.jpg','<p>Emotron industrial drives (VFDs) from CG Power — FDU and VFX series for general and heavy-duty applications, FlowDrive for pump optimisation, VSS/VSX compact drives, solar VSR drives, and lift-specific DSV/GSV units. Variable speed control that saves energy, extends equipment life, and improves process control across every industry.</p>',NULL,1,'motor/drives-and-automation/industrial-drives',NULL,NULL,0,1),(107,105,'Soft Starters','unnamed.jpg','<p>Soft starters deliver smooth, controlled motor starting without the cost of a full VFD — Emotron MSF 2.0 and TSA units ramp voltage gradually, eliminating mechanical shock to couplings, belts, and pumps while limiting inrush current. Ideal for fixed-speed pumps, compressors, and conveyors where starting stress is the concern, not speed control.</p>',NULL,2,'motor/drives-and-automation/soft-starters',NULL,NULL,0,1),(108,101,'NEMA Frame Motors',NULL,'<p>NEMA frame motors built to North American dimensional standards — B42, B48, 56 frame, and 100S sizes for export equipment manufacturers and imported machinery replacement. Correct NEMA mounting dimensions, voltage ratings (115/230V, 208-230/460V), and UL-recognised construction. BES cross-references NEMA to IEC equivalents when transitions make sense.</p>',NULL,0,'motor/fhp-commercial-motors/nema-frame-motors',NULL,NULL,0,1),(109,101,'General Purpose Body Motors',NULL,'<p>General purpose body motors in the construction that suits your environment — RHINO series rugged cast iron for tough industrial duty, SHEETAL series value cast iron for standard applications, ELiTE aluminium die-cast for weight-sensitive and corrosion-prone installs, and Comfort Plus extruded aluminium for premium thermal performance.</p>',NULL,0,'motor/fhp-commercial-motors/general-purpose-body-motors',NULL,NULL,0,1);
